# 1. 只读：算 WCU（也是语法校验 —— 不合法的规则在这里报错）
aws wafv2 check-capacity --scope "$SCOPE" --region "$REGION" --rules file://rules.json --cli-binary-format raw-in-base64-out

# 2. 建规则组（capacity 建后不可改：取第 1 步结果 × 1.2）
CAPACITY="${CAPACITY:-50}"
arn=$(aws wafv2 create-rule-group --name radar-ev-40bbda4fb2090dde-pack --scope "$SCOPE" --region "$REGION" --capacity "$CAPACITY" --rules file://rules.json --cli-binary-format raw-in-base64-out --visibility-config SampledRequestsEnabled=true,CloudWatchMetricsEnabled=true,MetricName=radarev40bbda4fb2090ddepack --query Summary.ARN --output text)

