#    不加 raw-in-base64-out：get-web-acl 输出里已有规则的 SearchString 是 base64，原样回传才不会被二次编码
aws wafv2 get-web-acl --name "$ACL_NAME" --id "$ACL_ID" --scope "$SCOPE" --region "$REGION" > acl.json
jq --arg arn "$arn" '{Name: .WebACL.Name, Scope: env.SCOPE, Id: .WebACL.Id, LockToken: .LockToken, DefaultAction: .WebACL.DefaultAction, VisibilityConfig: .WebACL.VisibilityConfig} + (.WebACL | with_entries(select(.key | IN("Description", "CustomResponseBodies", "CaptchaConfig", "ChallengeConfig", "TokenDomains", "AssociationConfig")))) + {Rules: (.WebACL.Rules + [{"Name": "radar-ev-40bbda4fb2090dde-pack", "Priority": 9999, "Statement": {"RuleGroupReferenceStatement": {"ARN": $arn}}, "OverrideAction": {"Count": {}}, "VisibilityConfig": {"SampledRequestsEnabled": true, "CloudWatchMetricsEnabled": true, "MetricName": "radarev40bbda4fb2090ddepack"}}])}' acl.json > update.json
# 若你的 ACL 已用 Priority 9999，先把 update.json 里这条改成未用的值
aws wafv2 update-web-acl --cli-input-json file://update.json --region "$REGION"
rm -f rules.json update.json   # 不留含密钥 / 规则副本的文件

